-- Purpose: raw-source reconciliation for the FORECAST training set (HZL_DEMO_01, ZSPR/ZSPN, net consumption 261-262, 2023-01-01..2025-12-31): series, total and date range per material type.
-- Result rows: 2 (ZSPR 3707 series / 478717.143, ZSPN 2253 series / 264547.184; min date 2023-01-31, max date 2025-12-31)
-- Data asset id: preview only
WITH MV AS (SELECT MATERIAL_ID, PLANT_ID, POSTING_DATE, MOVEMENT_TYPE, QUANTITY FROM VEDANTA_POC.FACT_MATERIAL_MOVEMENT_PART_001 UNION ALL SELECT MATERIAL_ID, PLANT_ID, POSTING_DATE, MOVEMENT_TYPE, QUANTITY FROM VEDANTA_POC.FACT_MATERIAL_MOVEMENT_PART_002 UNION ALL SELECT MATERIAL_ID, PLANT_ID, POSTING_DATE, MOVEMENT_TYPE, QUANTITY FROM VEDANTA_POC.FACT_MATERIAL_MOVEMENT_PART_003 UNION ALL SELECT MATERIAL_ID, PLANT_ID, POSTING_DATE, MOVEMENT_TYPE, QUANTITY FROM VEDANTA_POC.FACT_MATERIAL_MOVEMENT_PART_004) SELECT DM.MATERIAL_TYPE, COUNT(DISTINCT MV.MATERIAL_ID) AS SERIES, SUM(CASE WHEN MV.MOVEMENT_TYPE='261' THEN MV.QUANTITY WHEN MV.MOVEMENT_TYPE='262' THEN -MV.QUANTITY ELSE 0 END) AS NET_TOTAL, MIN(MV.POSTING_DATE) AS MIN_D, MAX(MV.POSTING_DATE) AS MAX_D FROM MV JOIN VEDANTA_POC.DIM_MATERIAL DM ON DM.MATERIAL_ID=MV.MATERIAL_ID WHERE MV.PLANT_ID='HZL_DEMO_01' AND DM.MATERIAL_TYPE IN ('ZSPR','ZSPN') AND MV.MOVEMENT_TYPE IN ('261','262') AND MV.POSTING_DATE >= '2023-01-01' AND MV.POSTING_DATE <= '2025-12-31' GROUP BY DM.MATERIAL_TYPE
